def reward_arithmetic_consistency_check(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        thinking = extract_thinking(response) or ''

        # Extract simple arithmetic expressions: A op B = C
        # Pattern: number (operator) number (equals) number
        pattern = r'(\d+\.?\d*)\s*([+\-*/])\s*(\d+\.?\d*)\s*=\s*(\d+\.?\d*)'
        matches = re.findall(pattern, thinking)

        errors = 0
        total_checks = 0
        for a, op, b, c in matches:
            try:
                a_val = float(a)
                b_val = float(b)
                c_val = float(c)

                # Skip trivial or zero divisions
                if op == '/' and b_val == 0:
                    continue

                if op == '+':
                    calc = a_val + b_val
                elif op == '-':
                    calc = a_val - b_val
                elif op == '*':
                    calc = a_val * b_val
                elif op == '/':
                    calc = a_val / b_val
                else:
                    continue

                total_checks += 1
                # Allow small floating point error
                if abs(calc - c_val) > 1e-6:
                    errors += 1
            except:
                pass

        score = 2.0
        if total_checks > 0:
            if errors > 0:
                score -= 2.0 * (errors / total_checks)
                # Heavy penalty if first calculation is wrong
                if matches and abs(float(matches[0][0]) + (float(matches[0][2]) if matches[0][1]=='+' else 0) - float(matches[0][3])) > 1e-6:
                    score -= 1.0
            else:
                score += 1.0
        else:
            # No checks found, neutral
            score = 0.0

        scores.append(max(-2.0, min(5.0, score)))
    return scores
